<?php
require_once __DIR__.'/includes/auth.php';requireLogin();$pdo=db();$uid=userId();$pageTitle='Pencarian';$activePage='pencarian.php';$keyword=trim((string)($_GET['keyword']??''));$kind=$_GET['kind']??'all';$category=trim((string)($_GET['category']??''));$from=validDate((string)($_GET['from']??''))?$_GET['from']:'';$to=validDate((string)($_GET['to']??''))?$_GET['to']:'';$min=parseAmount($_GET['min']??0);$max=parseAmount($_GET['max']??0);$sort=$_GET['sort']??'newest';$results=[];
if($keyword!==''||$category!==''||$from!==''||$to!==''||$min>0||$max>0){$where=['user_id=?'];$params=[$uid];if($keyword!==''){$where[]='(category LIKE ? OR description LIKE ?)';$params[]="%{$keyword}%";$params[]="%{$keyword}%";}if($category!==''){$where[]='category=?';$params[]=$category;}if($from!==''){$where[]='transaction_date>=?';$params[]=$from;}if($to!==''){$where[]='transaction_date<=?';$params[]=$to;}if($min>0){$where[]='amount>=?';$params[]=$min;}if($max>0){$where[]='amount<=?';$params[]=$max;}$types=$kind==='income'?' AND type="income"':($kind==='expense'?' AND type="expense"':'');$order=$sort==='oldest'?'transaction_date ASC':($sort==='largest'?'amount DESC':($sort==='smallest'?'amount ASC':'transaction_date DESC'));$st=$pdo->prepare('SELECT transaction_date date,type,category,description,amount FROM transactions WHERE '.implode(' AND ',$where).$types.' ORDER BY '.$order.',id DESC');$st->execute($params);foreach($st as $row){$row['source']='Transaksi';$results[]=$row;}}
$st=$pdo->prepare('SELECT name,category,description,amount,due_date date,status FROM bills WHERE user_id=? ORDER BY due_date DESC');$st->execute([$uid]);$billResults=$st->fetchAll();if($keyword!==''){foreach($billResults as $row){if(stripos($row['name'].' '.$row['category'].' '.$row['description'],$keyword)!==false){$row['type']='bill';$row['source']='Tagihan';$results[]=$row;}}}$categories=$pdo->prepare('SELECT DISTINCT category FROM transactions WHERE user_id=? ORDER BY category');$categories->execute([$uid]);$categoryOptions=$categories->fetchAll(PDO::FETCH_COLUMN);$user=currentUser($pdo);require __DIR__.'/includes/header.php';
?>
<div class="page-heading"><div><p class="eyebrow">Temukan catatan</p><h1>Pencarian Keuangan</h1><p>Cari transaksi, tagihan, dan detail penting dari satu tempat.</p></div></div>
<form class="card toolbar no-print" method="get"><div class="toolbar-form"><input class="input search-input" name="keyword" value="<?=e($keyword)?>" placeholder="Keyword, deskripsi, kategori..."><select class="select" name="kind"><option value="all" <?=$kind==='all'?'selected':''?>>Semua transaksi</option><option value="income" <?=$kind==='income'?'selected':''?>>Pemasukan</option><option value="expense" <?=$kind==='expense'?'selected':''?>>Pengeluaran</option></select><select class="select" name="category"><option value="">Semua kategori</option><?php foreach($categoryOptions as $cat):?><option <?=$category===$cat?'selected':''?>><?=e($cat)?></option><?php endforeach;?></select><input class="input" type="date" name="from" value="<?=e($from)?>"><input class="input" type="date" name="to" value="<?=e($to)?>"><input class="input" inputmode="numeric" name="min" placeholder="Min nominal" value="<?=e($_GET['min']??'')?>"><input class="input" inputmode="numeric" name="max" placeholder="Maks nominal" value="<?=e($_GET['max']??'')?>"><select class="select" name="sort"><option value="newest">Terbaru</option><option value="oldest" <?=$sort==='oldest'?'selected':''?>>Terlama</option><option value="largest" <?=$sort==='largest'?'selected':''?>>Nominal terbesar</option><option value="smallest" <?=$sort==='smallest'?'selected':''?>>Nominal terkecil</option></select><button class="btn btn-primary" type="submit"><i data-lucide="search"></i> Cari</button></div></form>
<section class="card"><div class="card-header"><div><h2 class="card-title">Hasil pencarian</h2><p class="card-subtitle"><?=number_format(count($results),0,',','.')?> hasil ditemukan</p></div></div><?php if(!$results):?><div class="empty-state"><div class="empty-icon"><i data-lucide="search-x"></i></div><strong>Belum ada hasil.</strong><p>Gunakan keyword atau filter lain untuk menemukan catatanmu.</p></div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Sumber</th><th>Kategori</th><th>Deskripsi</th><th>Nominal</th><th>Status</th></tr></thead><tbody><?php foreach($results as $row):?><tr><td><?=e(date('d/m/Y',strtotime($row['date'])))?></td><td><span class="badge neutral"><?=e($row['source'])?></span></td><td><?=e($row['category']??'—')?></td><td><?=e($row['description']??$row['name']??'—')?></td><td class="amount <?=($row['type']??'')==='income'?'positive':(($row['type']??'')==='expense'?'negative':'')?>"><?=formatRupiah($row['amount'])?></td><td><?=isset($row['status'])?e($row['status']):'—'?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php require __DIR__.'/includes/footer.php'; ?>